    lines.push(fg(t.border.active, `\u250C${"\u2500".repeat(dWidth - 2)}\u2510`));
    lines.push(`\u2502 ${padToWidth(bold(fg(t.text.action, " SAURON UNIFIED/SPLIT DIFF VIEWER")), dWidth - 4)} \u2502`);
    lines.push(`\u251C${"\u2500".repeat(dWidth - 2)}\u2524`);
