import { existsSync as existsSync14, readFileSync as readFileSync8, writeFileSync as writeFileSync8, mkdirSync as mkdirSync4, readdirSync as readdirSync2, renameSync as renameSync4 } from "fs";
import { join as join11 } from "path";
import { randomUUID as randomUUID2 } from "crypto";

class PlaybookStore {
  playbooks = new Map;
  traces = [];
  constructor() {
    this.ensureDir();
    this.loadSeeds();
    this.load();
  }
  getDir() {
    return join11(configManager.getConfig().sauronDir, "playbooks");
  }
  ensureDir() {
    const dir = this.getDir();
    if (!existsSync14(dir)) {
      try {
        mkdirSync4(dir, { recursive: true });
      } catch {}
    }
  }
  loadSeeds() {
    const seeds = [
      {
        id: "pb_host_recon",
        name: "Host Architecture & Kernel Recon",
        category: "recon",
        description: "Standard reconnaissance playbook for operating system, kernel release, and hardware architecture",
        template: [
          { id: "step_1", tool: "bash", argsTemplate: { command: "uname -s && uname -m && uname -r" } },
          { id: "step_2", tool: "bash", argsTemplate: { command: "uptime && whoami" }, dependsOn: ["step_1"] }
        ],
        successRate: 1,
        usageCount: 10,
        sourceTraceIds: ["seed_recon"]
      },
      {
        id: "pb_priv_audit",
        name: "User Identity & Permission Audit",
        category: "privilege-audit",
        description: "Audit current process UID, GID, group memberships, and user context",
        template: [
          { id: "step_1", tool: "bash", argsTemplate: { command: "id && whoami" } },
          { id: "step_2", tool: "bash", argsTemplate: { command: "groups" }, dependsOn: ["step_1"] }
        ],
        successRate: 1,
        usageCount: 8,
        sourceTraceIds: ["seed_priv"]
      },
      {
        id: "pb_network_discovery",
        name: "Network Interface & Link Enumeration",
        category: "network-discovery",
        description: "Enumerate network interfaces, assigned IP addresses, and routing state",
        template: [
          { id: "step_1", tool: "bash", argsTemplate: { command: "ip addr || ifconfig -a" } },
          { id: "step_2", tool: "bash", argsTemplate: { command: "ip route || netstat -rn" }, dependsOn: ["step_1"] }
        ],
        successRate: 1,
        usageCount: 6,
        sourceTraceIds: ["seed_net"]
      }
    ];
    for (const p of seeds) {
      this.playbooks.set(p.id, p);
    }
  }
  recordTrace(trace) {
    this.traces.push(trace);
    if (this.traces.length > 200) {
      this.traces.shift();
    }
    if (trace.outcome === "success" && trace.steps.length > 0) {
      this.extractPlaybook(trace);
    }
  }
  extractPlaybook(trace) {
    const targetName = `Playbook: ${trace.goal.slice(0, 40)}`;
    const existing = Array.from(this.playbooks.values()).find((p) => p.name.toLowerCase() === targetName.toLowerCase());
    if (existing) {
      existing.usageCount++;
      existing.successRate = (existing.successRate * (existing.usageCount - 1) + 1) / existing.usageCount;
      this.savePlaybook(existing);
      return existing;
    }
    const category = this.categorizeGoal(trace.goal);
    const playbook = {
      id: `pb_${randomUUID2().slice(0, 8)}`,
      name: targetName,
      category,
      description: `Autonomous playbook distilled from successful goal: "${trace.goal}"`,
      template: trace.steps.map((s, idx) => ({
        id: `step_${idx + 1}`,
        tool: s.tool,
        argsTemplate: Object.fromEntries(Object.entries(s.args).map(([k, v]) => [k, typeof v === "string" ? v : JSON.stringify(v)])),
        dependsOn: idx > 0 ? [`step_${idx}`] : undefined
      })),
      successRate: 1,
      usageCount: 1,
      sourceTraceIds: [trace.id]
    };
    this.playbooks.set(playbook.id, playbook);
    this.savePlaybook(playbook);
    return playbook;
  }
  recall(goal, topK = 2) {
    const category = this.categorizeGoal(goal);
    const matches = [];
    const goalLower = goal.toLowerCase();
    for (const pb of this.playbooks.values()) {
      let score = 0;
      if (pb.category === category)
        score += 3;
      const rawTitle = pb.name.toLowerCase().replace("playbook: ", "");
      if (goalLower.includes(rawTitle) || rawTitle.includes(goalLower)) {
        score += 15;
      }
      const keywords = pb.name.toLowerCase().split(/\s+/);
      for (const kw of keywords) {
        if (kw.length > 3 && goalLower.includes(kw))
          score += 2;
      }
      score += pb.successRate * 2;
      score += Math.min(pb.usageCount * 0.1, 1);
      matches.push({ playbook: pb, score });
    }
    matches.sort((a, b) => b.score - a.score);
    return matches.slice(0, topK).map((m) => m.playbook);
  }
  instantiate(playbook, bindings = {}) {
    return playbook.template.map((step) => {
      const instantiatedArgs = {};
      for (const [k, v] of Object.entries(step.argsTemplate)) {
        let replaced = v;
        for (const [bKey, bVal] of Object.entries(bindings)) {
          replaced = replaced.replaceAll(`{{${bKey}}}`, bVal);
        }
        instantiatedArgs[k] = replaced;
      }
      return {
        ...step,
        argsTemplate: instantiatedArgs
      };
    });
  }
  reportOutcome(playbookId, success) {
    const pb = this.playbooks.get(playbookId);
    if (!pb)
      return;
    pb.usageCount++;
    const weight = success ? 1 : 0;
    pb.successRate = (pb.successRate * (pb.usageCount - 1) + weight) / pb.usageCount;
    this.savePlaybook(pb);
  }
  categorizeGoal(goal) {
    const g = goal.toLowerCase();
    if (g.includes("user") || g.includes("identity") || g.includes("permission") || g.includes("whoami")) {
      return "privilege-audit";
    }
    if (g.includes("net") || g.includes("ip") || g.includes("port") || g.includes("interface")) {
      return "network-discovery";
    }
    if (g.includes("log") || g.includes("auth") || g.includes("audit")) {
      return "log-analysis";
    }
    return "recon";
  }
  savePlaybook(playbook) {
    try {
      const filePath = join11(this.getDir(), `${playbook.id}.json`);
      const tmpPath = `${filePath}.${Date.now()}.tmp`;
      writeFileSync8(tmpPath, JSON.stringify(playbook, null, 2), { mode: 384, encoding: "utf-8" });
      renameSync4(tmpPath, filePath);
    } catch {}
  }
  load() {
    try {
      const dir = this.getDir();
      if (!existsSync14(dir))
        return;
      const files = readdirSync2(dir).filter((f) => f.endsWith(".json"));
      for (const file of files) {
        const raw = readFileSync8(join11(dir, file), "utf-8");
        const pb = JSON.parse(raw);
        if (pb && pb.id && Array.isArray(pb.template)) {
          this.playbooks.set(pb.id, pb);
        }
      }
    } catch {}
  }
  listPlaybooks() {
    return Array.from(this.playbooks.values());
  }
  clear() {
    this.playbooks.clear();
    this.traces = [];
    this.loadSeeds();
  }
}
var playbookStore = new PlaybookStore;

// src/tui/views.ts
class SessionTabBar {
  render(width, activeSessionTitle, sessionCount, t) {
    const tab1 = ` \uDB80\uDD4D ${activeSessionTitle.slice(0, 18)} `;
    const tab2 = ` + New Session `;
    const helpHint = ` ctrl+p palette \u2502 <leader>m model \u2502 ctrl+x leader `;
    const activeFormatted = fgBg(t.text.base, t.background.activeTab, bold(tab1));
    const inactiveFormatted = fg(t.text.muted, tab2);
    const hintFormatted = fg(t.text.muted, helpHint);
    const leftPart = `${activeFormatted}\u2502${inactiveFormatted}`;
    const leftLen = visibleLen(leftPart);
    const hintLen = visibleLen(hintFormatted);
    const padding = Math.max(0, width - leftLen - hintLen);
    return `${leftPart}${" ".repeat(padding)}${hintFormatted}`;
  }
}

class SidebarPane {
  render(width, height, t) {
    const lines = [];
    const activeSession = sessionStore.getActiveSession();
    const configuredModel = chatRouter.getDefaultModel();
    const lastRouted = chatRouter.lastRoutedModel;
    const activeModel = lastRouted && lastRouted !== configuredModel ? lastRouted : configuredModel;
    const playbooks = playbookStore.listPlaybooks();
    const border = "\u2500".repeat(width - 2);
    lines.push(fg(t.border.base, `\u250C${border}\u2510`));
    lines.push(`\u2502 ${padToWidth(bold(fg(t.text.accent, "SAURON SIDEBAR")), width - 4)} \u2502`);
    lines.push(fg(t.border.base, `\u251C${border}\u2524`));
    lines.push(`\u2502 ${padToWidth(`${bold(fg(t.text.base, "Model:"))} ${fg(t.text.accent, activeModel.slice(0, width - 12))}`, width - 4)} \u2502`);
    lines.push(`\u2502 ${padToWidth(`${bold(fg(t.text.base, "Session:"))} ${fg(t.text.muted, activeSession.title.slice(0, width - 14))}`, width - 4)} \u2502`);
    lines.push(`\u2502 ${padToWidth(`${bold(fg(t.text.base, "Messages:"))} ${fg(t.text.info, String(activeSession.messages.length))}`, width - 4)} \u2502`);
    lines.push(fg(t.border.base, `\u251C${border}\u2524`));
    lines.push(`\u2502 ${padToWidth(bold(fg(t.text.action, "TACTICAL PLAYBOOKS")), width - 4)} \u2502`);
    for (let i = 0;i < Math.min(3, playbooks.length); i++) {
      const pb = playbooks[i];
      const pbStr = `\u2022 ${pb.name}`.slice(0, width - 6);
      lines.push(`\u2502 ${padToWidth(fg(t.text.muted, pbStr), width - 4)} \u2502`);
    }
    lines.push(fg(t.border.base, `\u251C${border}\u2524`));
    lines.push(`\u2502 ${padToWidth(bold(fg(t.text.success, "MCP SERVERS: 2 ACTIVE")), width - 4)} \u2502`);
    lines.push(`\u2502 ${padToWidth(fg(t.text.muted, "\u2022 Kali SecSuite Engine"), width - 4)} \u2502`);
    lines.push(`\u2502 ${padToWidth(fg(t.text.muted, "\u2022 Local Filesystem MCP"), width - 4)} \u2502`);
    while (lines.length < height - 1) {
      lines.push(`\u2502 ${" ".repeat(width - 4)} \u2502`);
    }
    lines.push(fg(t.border.base, `\u2514${border}\u2518`));
    return lines;
  }
}

class MessageCardRenderer {
  renderMessage(msg, width, t) {
    const lines = [];
    const isUser = msg.role === "user";
    const isSystem = msg.role === "system";
    const maxContentWidth = Math.max(10, width - 4);
    if (isUser) {
      const headerStr = ` USER  ${new Date(msg.timestamp).toLocaleTimeString()}`;
      lines.push(fgBg(t.text.base, t.background.selection, bold(padToWidth(` ${headerStr}`, width - 2))));
      let text = msg.content;
      text = text.replace(/@([\w.-]+)/g, (_, name) => fg(t.text.extmarkFile, `@${name}`));
      text = text.replace(/\/([\w.-]+)/g, (_, cmd) => fg(t.text.extmarkAgent, `/${cmd}`));
      const wrapped = wrapText(text, maxContentWidth);
      for (const line of wrapped) {
        lines.push(`  ${padToWidth(line, maxContentWidth)}`);
      }
      lines.push("");
      return lines;
    }
    if (isSystem) {
      const wrapped = wrapText(`[SYSTEM] ${msg.content}`, maxContentWidth);
      for (const line of wrapped) {
        lines.push(fg(t.text.muted, `  ${padToWidth(line, maxContentWidth)}`));
      }
      lines.push("");
      return lines;
    }
    const modelTag = msg.name || chatRouter.getDefaultModel();
    const headerStr = ` SAURON (${modelTag}) `;
    lines.push(fg(t.text.accent, bold(headerStr)));
    const rawLines = msg.content.split(`
`);
    let inCode = false;
    for (const rawL of rawLines) {
      if (rawL.startsWith("```")) {
        inCode = !inCode;
        lines.push(fg(t.syntax.comment, `  ${padToWidth(rawL.slice(0, maxContentWidth), maxContentWidth)}`));
        continue;
      }
      if (inCode) {
        const wrappedCode = wrapText(rawL, maxContentWidth - 4);
        for (const cl of wrappedCode) {
          lines.push(fg(t.syntax.string, `    ${padToWidth(cl, maxContentWidth - 4)}`));
        }
      } else if (rawL.startsWith("> ")) {
        const wrappedReasoning = wrapText(rawL, maxContentWidth - 2);
        for (const rl of wrappedReasoning) {
          lines.push(fg(t.text.muted, italic(`  ${padToWidth(rl, maxContentWidth - 2)}`)));
        }
      } else {
        const wrappedNormal = wrapText(rawL, maxContentWidth - 2);
        for (const nl of wrappedNormal) {
          lines.push(`  ${padToWidth(nl, maxContentWidth - 2)}`);
        }
      }
    }
    lines.push("");
    return lines;
  }
  renderBlockToolCard(name, args, status, output, width, t) {
    const lines = [];
    const boxW = Math.min(width - 4, 84);
    const border = "\u2500".repeat(boxW - 2);
    let statusBadge = fgBg("#ffffff", t.background.badge, " RUNNING ");
    if (status === "success")
      statusBadge = fgBg("#ffffff", t.text.success, " SUCCESS ");
    if (status === "failed")
      statusBadge = fgBg("#ffffff", t.text.error, " FAILED ");
    lines.push(fg(t.border.base, `\u250C${border}\u2510`));
    const title = `TOOL ${name.toUpperCase()} ${statusBadge}`;
    lines.push(`\u2502 ${padToWidth(title, boxW - 4)} \u2502`);
    lines.push(fg(t.border.base, `\u251C${border}\u2524`));
    const argStr = JSON.stringify(args);
    lines.push(`\u2502 ${padToWidth(fg(t.text.muted, `Args: ${argStr.slice(0, boxW - 10)}`), boxW - 4)} \u2502`);
    if (output) {
      lines.push(fg(t.border.base, `\u251C${border}\u2524`));
      for (const l of output.split(`
`).slice(0, 6)) {
        lines.push(`\u2502 ${padToWidth(fg(t.text.base, l.slice(0, boxW - 6)), boxW - 4)} \u2502`);
      }
    }
    lines.push(fg(t.border.base, `\u2514${border}\u2518`));
    return lines;
  }
}

class PromptComposer {
  spinnerFrames = ["\u280B", "\u2819", "\u2839", "\u2838", "\u283C", "\u2834", "\u2826", "\u2827", "\u2807", "\u280F"];
  spinnerIndex = 0;
  renderPrompt(buffer, cursorOffset, width, isBusy, t, statusNote, busyStartTime) {
    const lines = [];
    const boxW = width;
    const border = "\u2500".repeat(boxW - 2);
    let modeBadge = fgBg("#ffffff", t.text.accent, " NORMAL ");
    if (buffer.startsWith("!"))
      modeBadge = fgBg("#ffffff", t.text.error, " SHELL ! ");
    if (buffer.startsWith("/"))
      modeBadge = fgBg("#ffffff", t.text.action, " COMMAND / ");
    if (buffer.includes("@"))
      modeBadge = fgBg("#ffffff", t.text.extmarkFile, " ATTACH @ ");
    lines.push(fg(t.border.focus, `\u250C${border}\u2510`));
    const cur = Math.max(0, Math.min(buffer.length, cursorOffset));
    const linesText = buffer.split(`
`);
    const maxInnerW = Math.max(10, boxW - 4);
    const MAX_VISIBLE_ROWS = 8;
    let cursorLine = 0;
    if (linesText.length === 0 || buffer === "") {
      lines.push(`\u2502 ${padToWidth(`${modeBadge} ${dim("Type prompt, @file, /command, or !shell...")}\u2588`, maxInnerW)} \u2502`);
    } else {
      let posTracker = 0;
      for (let i = 0;i < linesText.length; i++) {
        const lineEnd = posTracker + linesText[i].length;
        if (cur >= posTracker && cur <= lineEnd) {
          cursorLine = i;
          break;
        }
        posTracker = lineEnd + 1;
      }
      let startLineIdx = 0;
      let endLineIdx = linesText.length;
      if (linesText.length > MAX_VISIBLE_ROWS) {
        startLineIdx = Math.max(0, Math.min(linesText.length - MAX_VISIBLE_ROWS, cursorLine - 3));
        endLineIdx = Math.min(linesText.length, startLineIdx + MAX_VISIBLE_ROWS);
      }
      let lineStart = 0;
      for (let i = 0;i < linesText.length; i++) {
        const rawL = linesText[i];
        const col = cur - lineStart;
        const isCurrentLine = col >= 0 && col <= rawL.length;
        lineStart += rawL.length + 1;
        if (i < startLineIdx || i >= endLineIdx)
          continue;
        let l = rawL;
        if (isCurrentLine) {
          const under = col < rawL.length ? rawL[col] : " ";
          l = rawL.slice(0, col) + "\x1B[7m" + under + "\x1B[27m" + (col < rawL.length ? rawL.slice(col + 1) : "");
        }
        if (visibleLen(l) > maxInnerW) {
          if (isCurrentLine) {
            const hStart = Math.max(0, Math.min(rawL.length - maxInnerW, col - Math.floor(maxInnerW / 2)));
            l = l.slice(hStart, hStart + maxInnerW);
          } else {
            l = l.slice(0, maxInnerW);
          }
        }
        const formatted = rawL.startsWith("!") ? fg(t.text.error, l) : rawL.startsWith("/") ? fg(t.text.action, l) : l;
        lines.push(`\u2502 ${padToWidth(formatted, maxInnerW)} \u2502`);
      }
    }
    const scrollHint = linesText.length > MAX_VISIBLE_ROWS ? ` [Showing lines ${cursorLine + 1}/${linesText.length}]` : "";
    lines.push(fg(t.border.focus, `\u251C${border.slice(0, Math.max(0, border.length - scrollHint.length))}${scrollHint}\u2524`));
    this.spinnerIndex = (this.spinnerIndex + 1) % this.spinnerFrames.length;
    const elapsed = isBusy && busyStartTime ? Math.max(0, Math.floor((Date.now() - busyStartTime) / 1000)) : 0;
    const elapsedStr = isBusy ? ` (${elapsed}s)` : "";
    const busyLabel = (statusNote ? statusNote : "Thinking...") + elapsedStr;
    const spinStr = isBusy ? fg(t.text.warning, `${this.spinnerFrames[this.spinnerIndex]} ${busyLabel}`) : fg(t.text.success, "\u25CF Ready");
    const modelBadge = fgBg(t.text.base, t.background.activeTab, ` ${chatRouter.getDefaultModel()} `);
    const agentBadge = fg(t.text.extmarkAgent, " [Sauron Agent] ");
    const footerLeft = `${spinStr} \u2502 ${modelBadge} \u2502 ${agentBadge}`;
    const footerRight = fg(t.text.muted, isBusy ? "esc to stop prompt, ctrl+c to exit" : "press return to submit, shift+return for newline");
    const leftVis = visibleLen(footerLeft);
    const rightVis = visibleLen(footerRight);
    const pad = Math.max(0, boxW - 4 - leftVis - rightVis);
    lines.push(`\u2502 ${footerLeft}${" ".repeat(pad)}${footerRight} \u2502`);
    lines.push(fg(t.border.focus, `\u2514${border}\u2518`));
    return lines;
  }
}

// src/tui/components.ts
var RESET = "\x1B[0m";
var BOLD = "\x1B[1m";
var DIM = "\x1B[2m";
var COLOR_HEADER = "\x1B[38;2;99;102;241m";
var COLOR_CYAN = "\x1B[38;2;56;189;248m";
var COLOR_GREEN = "\x1B[38;2;52;211;153m";
var COLOR_PURPLE = "\x1B[38;2;168;85;247m";
var COLOR_YELLOW = "\x1B[38;2;251;191;36m";
var COLOR_RED = "\x1B[38;2;248;113;113m";
var COLOR_GRAY = "\x1B[38;2;156;163;175m";

class HeaderComponent {
  render(width, model, provider, mode, sessionId) {
    const title = `${BOLD}\uD83D\uDC41\uFE0F  SAURON v2.0${RESET}${COLOR_HEADER}  \u2022  ${COLOR_CYAN}OPENCODE TUI${RESET}${COLOR_HEADER}  \u2022  ${COLOR_GREEN}ACTIVE ENGINE${RESET}`;
    const statusLine = `${DIM}Model:${RESET} ${COLOR_CYAN}${model}${RESET}  ${DIM}Provider:${RESET} ${COLOR_GREEN}${provider}${RESET}  ${DIM}Mode:${RESET} ${COLOR_YELLOW}${mode}${RESET}  ${DIM}Session:${RESET} ${COLOR_GRAY}${sessionId.slice(-8)}${RESET}`;
    const topBorder = `${COLOR_HEADER}\u256D` + "\u2500".repeat(Math.max(10, width - 2)) + `\u256E${RESET}`;
    const titleRow = `${COLOR_HEADER}\u2502${RESET}  ${title}`.padEnd(width + 35) + `${COLOR_HEADER}\u2502${RESET}`;
    const midBorder = `${COLOR_HEADER}\u251C` + "\u2500".repeat(Math.max(10, width - 2)) + `\u2524${RESET}`;
    const statusRow = `${COLOR_HEADER}\u2502${RESET}  ${statusLine}`.padEnd(width + 35) + `${COLOR_HEADER}\u2502${RESET}`;
    const botBorder = `${COLOR_HEADER}\u2570` + "\u2500".repeat(Math.max(10, width - 2)) + `\u256F${RESET}`;
    return [topBorder, titleRow, midBorder, statusRow, botBorder];
  }
}
var ESCAPE_RE = /\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b[PX^_].*?\x1b\\|[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g;
function stripAnsi2(s) {
  return s ? s.replace(ESCAPE_RE, "") : "";
}
function highlightVisibleRange(line, colStart, colEnd) {
  if (colStart > colEnd) {
    const tmp = colStart;
    colStart = colEnd;
    colEnd = tmp;
  }
  let result = "";
  let visCol = 0;
  let inHighlight = false;
  let i = 0;
  while (i < line.length) {
    if (line[i] === "\x1B") {
      const match = line.slice(i).match(/^(\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b[PX^_].*?\x1b\\)/);
      if (match) {
        result += match[0];
        i += match[0].length;
        continue;
      }
    }
    visCol++;
    if (!inHighlight && visCol >= colStart && visCol <= colEnd) {
      result += "\x1B[7m";
      inHighlight = true;
    } else if (inHighlight && visCol > colEnd) {
      result += "\x1B[27m";
      inHighlight = false;
    }
    result += line[i];
    i++;
  }
  if (inHighlight) {
    result += "\x1B[27m";
  }
  return result;
}

class TranscriptComponent {
  render(width, messages, scrollOffset = 0) {
    const lines = [];
    if (messages.length === 0) {
      lines.push(`${DIM}  No messages yet. Type a question or /help to view commands.${RESET}`);
      return lines;
    }
    for (const msg of messages) {
      const safeContent = stripAnsi2(msg.content);
      if (msg.role === "user") {
        lines.push(`${COLOR_CYAN}\u256D\u2500 \uD83D\uDC64 USER \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256E${RESET}`);
        lines.push(`\u2502 ${safeContent}`);
        lines.push(`${COLOR_CYAN}\u2570\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256F${RESET}`);
      } else if (msg.role === "assistant") {
        lines.push(`${COLOR_GREEN}\u256D\u2500 \uD83D\uDC41\uFE0F SAURON AI \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256E${RESET}`);
        const formatted = this.formatMarkdown(safeContent);
        for (const line of formatted.split(`
`)) {
          lines.push(`\u2502 ${line}`);
        }
        lines.push(`${COLOR_GREEN}\u2570\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256F${RESET}`);
      } else if (msg.role === "system") {
        lines.push(`${COLOR_YELLOW}\u25B6 ${safeContent}${RESET}`);
      }
    }
    return lines;
  }
  formatMarkdown(text) {
    return text.replace(/\*\*(.*?)\*\*/g, `${BOLD}$1${RESET}`).replace(/`([^`]+)`/g, `${COLOR_CYAN}$1${RESET}`);
  }
}

class ToolCardComponent {
  render(toolName, command, status, output) {
    const color = status === "success" ? COLOR_GREEN : status === "failed" ? COLOR_RED : COLOR_YELLOW;
    const icon = status === "success" ? "\u2713" : status === "failed" ? "\u2717" : "\u2699";
    const safeCmd = stripAnsi2(command);
    const header = `${color}\u26A1 [Tool: ${toolName}] ${icon} ${status.toUpperCase()}${RESET} ${DIM}cmd: "${safeCmd}"${RESET}`;
    const lines = [`${color}\u256D\u2500 ${header} \u2500\u256E${RESET}`];
    if (output) {
      const safeOutput = stripAnsi2(output);
      const outLines = safeOutput.split(`
`).slice(0, 5);
      for (const line of outLines) {
        lines.push(`\u2502 ${COLOR_GRAY}${line}${RESET}`);
      }
      if (safeOutput.split(`
`).length > 5) {
        lines.push(`\u2502 ${DIM}... (+${safeOutput.split(`
`).length - 5} lines hidden)${RESET}`);
      }
    }
    lines.push(`${color}\u2570\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256F${RESET}`);
    return lines;
  }
}

