class TerminalScreen {
  isRawMode = false;
  currentFrame = [];
  active = false;
  cleanupInstalled = false;
  onInterrupt;
  setInterruptHandler(fn) {
    this.onInterrupt = fn;
  }
  getSize() {
    return {
      columns: process.stdout.columns || 80,
      rows: process.stdout.rows || 24
    };
  }
  enterAlternateScreen() {
    this.active = true;
    this.setupCleanup();
    if (process.stdout.isTTY) {
      process.stdout.write("\x1B[?1049h");
      process.stdout.write("\x1B[?25h");
      if (process.stdin.setRawMode) {
        process.stdin.setRawMode(true);
        this.isRawMode = true;
      }
      process.stdin.resume();
    }
  }
  leaveAlternateScreen() {
    if (!this.active)
      return;
    this.active = false;
    if (process.stdout.isTTY) {
      if (this.isRawMode && process.stdin.setRawMode) {
        process.stdin.setRawMode(false);
        this.isRawMode = false;
      }
      process.stdout.write("\x1B[?1049l");
      process.stdout.write("\x1B[?25h");
      process.stdout.write(`\x1B[0m
`);
    }
  }
  setupCleanup() {
    if (this.cleanupInstalled)
      return;
    this.cleanupInstalled = true;
    const exitHandler = () => {
      this.leaveAlternateScreen();
    };
    process.on("SIGINT", () => {
      if (this.onInterrupt && this.onInterrupt()) {
        return;
      }
      exitHandler();
      process.exit(130);
    });
    process.on("SIGTERM", () => {
      exitHandler();
      process.exit(143);
    });
    process.on("uncaughtException", (err) => {
      exitHandler();
      console.error("[Terminal Panic] Uncaught exception:", err);
      process.exit(1);
    });
    process.on("unhandledRejection", (reason) => {
      exitHandler();
      console.error("[Terminal Panic] Unhandled rejection:", reason);
      process.exit(1);
    });
    process.on("exit", () => {
      exitHandler();
    });
  }
  renderFrame(lines) {
    if (!process.stdout.isTTY) {
      console.log(lines.join(`
`));
      return;
    }
    const { rows } = this.getSize();
    const frame = lines.slice(0, rows);
    process.stdout.write("\x1B[?2026h");
    process.stdout.write("\x1B[H\x1B[J");
    for (let i = 0;i < frame.length; i++) {
      process.stdout.write(frame[i] + `
`);
    }
    process.stdout.write("\x1B[?2026l");
    this.currentFrame = frame;
  }
}
